export const defaultChangesPolicy="Changes to deliverables\nIf either party requests a change to the agreed items, specifications or review rounds, Roll will outline the effect on the fee and timing. Both parties will confirm the change in writing before the extra or revised work begins.\n\nChanges to the schedule\nIf either party needs to move a date, they will let the other know as soon as possible. We will agree a revised schedule, including any effect on reviews, delivery and payment dates. A requested date is not confirmed until both parties agree.\n\nLate materials, feedback or payments\nRoll will flag what is missing and how it affects the work. Affected work may pause, and later milestones may move according to the delay and Roll's availability. Any additional cost will be quoted and agreed in writing before it is incurred.\n\nIf Roll is running late\nRoll will notify the client promptly, explain the impact and propose a revised delivery plan. Both parties will confirm the new dates in writing.\n\nKeeping one agreed version\nRoll will update the project and send a fresh link or PDF for confirmation. Previously issued links and PDFs remain snapshots of their original version.";
export const example=()=>({id:crypto.randomUUID(),changesPolicy:defaultChangesPolicy,title:'The space between',client:'Northlight Films',description:'A title sequence that sets the tone before the story begins.',deliverableItems:[{name:'Opening title sequence — 4K master',specs:'30 seconds · 3840 × 2160 · Square pixels · 4:2:2 · Rec.709'},{name:'Opening title sequence — HD master',specs:'30 seconds · 1920 × 1080 · Square pixels · 4:2:2 · Rec.709'}],deliverables:'One 30-second opening title sequence\nCreative direction, design & animation\n4K master + 1080p delivery',currency:'NZD',tax:'Excludes any applicable tax',rate:1200,days:12,costs:600,fee:15000,deposit:50,start:'2026-11-02',conceptDays:5,animationDays:8,reviewDays:2,reviews:2,finishDays:2,inputs:'Logo files in vector format\nFinal title and credit list\nPicture reference and technical delivery specs',terms:'The fee covers the deliverables and review rounds listed on this page.\nAdditional work or a change of direction will be quoted and agreed before proceeding.\nPlease send one consolidated set of feedback per review round.\nThe schedule depends on receiving materials, feedback and payments on time. If something moves, we will agree revised dates together.',paymentNote:'Deposit to book the project. Balance before release of final masters.',rights:'Usage rights, source files and any third-party licences to be agreed before work begins.'});
export function addDays(date,n){const d=new Date(date+'T12:00:00Z');let count=0;while(count<n){d.setUTCDate(d.getUTCDate()+1);if(d.getUTCDay()!==0&&d.getUTCDay()!==6)count++}return d.toISOString().slice(0,10)}
export function stages(p){let cursor=p.start;const list=[{name:'Kick-off',start:cursor,end:cursor,owner:'Together',color:'#bdd39d',body:`${p.client} supplies:\n${p.inputs}\n\nRoll confirms the brief and receives the ${p.deposit}% deposit.`}];function add(name,days,owner,color,body){const start=cursor;cursor=addDays(cursor,days);list.push({name,start,end:cursor,owner,color,body})}add('Direction',p.conceptDays,'Roll','#c6d8ac','Creative exploration, design and a proposed visual direction.');for(let i=0;i<p.reviews;i++){add(`Review ${i+1}`,p.reviewDays,p.client,'#c6cced',`Send one consolidated set of feedback within ${p.reviewDays} working day${p.reviewDays===1?'':'s'}.\n${i===0?'Approve the creative direction before animation begins.':'Review the animation and flag adjustments within the agreed scope.'}`);if(i===0)add('Animation',p.animationDays,'Roll','#b8cec5','Bring the approved direction to life through motion, timing and finishing.');else if(i<p.reviews-1)add('Refinements',p.finishDays,'Roll','#b8cec5','Apply the consolidated feedback before the next review.')}add('Final delivery',p.finishDays,'Roll','#e2c39d','Apply final agreed refinements and deliver the listed masters once the balance is paid.');return list}
export function clientProject(p){const {rate,days,costs,...safe}=p;return safe}
export function validate(p){return p&&typeof p.title==='string'&&p.title.length<=200&&typeof p.client==='string'&&['description','deliverables','inputs','terms','paymentNote','rights','tax'].every(k=>typeof p[k]==='string'&&p[k].length<=10000)&&(p.changesPolicy===undefined||(typeof p.changesPolicy==='string'&&p.changesPolicy.length<=10000))&&(p.deliverableItems===undefined||(Array.isArray(p.deliverableItems)&&p.deliverableItems.length>0&&p.deliverableItems.length<=30&&p.deliverableItems.every(v=>v&&typeof v.name==='string'&&v.name.trim().length>0&&v.name.length<=200&&typeof v.specs==='string'&&v.specs.length<=2000)))&&['NZD','USD','AUD','GBP','EUR'].includes(p.currency)&&Number.isFinite(p.fee)&&p.fee>=0&&p.fee<=1e9&&Number.isFinite(p.deposit)&&p.deposit>=0&&p.deposit<=100&&/^\d{4}-\d{2}-\d{2}$/.test(p.start)&&!Number.isNaN(Date.parse(p.start))&&['conceptDays','animationDays','reviewDays','finishDays','reviews'].every(k=>Number.isInteger(p[k])&&p[k]>=1&&p[k]<=90)&&p.reviews<=6}
export function encode(p){const bytes=new TextEncoder().encode(JSON.stringify(clientProject(p)));return btoa(Array.from(bytes,b=>String.fromCharCode(b)).join('')).replaceAll('+','-').replaceAll('/','_').replaceAll('=','')}
export function decode(s){if(s.length>100000)throw Error('Too large');const p=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(atob(s.replaceAll('-','+').replaceAll('_','/')),c=>c.charCodeAt(0))));if(!validate(p))throw Error('Invalid project');return p}

export function deliverableItems(p){return p.deliverableItems??p.deliverables.split('\n').filter(v=>v.trim()).map(name=>({name,specs:''}))}
